<?php
if (!isset($provider, $cfg, $from, $today)) { http_response_code(404); exit; }
$report=integration_report($provider, $from, $today);
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($provider->title())?> · Своя статистика</title><link rel="stylesheet" href="ui.css"></head><body><div class="shell"><header class="topbar"><a class="wordmark" href="index.php">своя<span>статистика</span></a><span class="edition">НА ВАШЕМ СЕРВЕРЕ</span><a class="quiet-link" href="help.php">Как подключить ↗</a></header><main><div class="heading"><div><p class="eyebrow"><?=esc($cfg['title'])?></p><h1><?=esc($provider->title())?></h1><p class="muted date-range"><?=esc($from->format('d.m'))?> · <?=esc($today->format('d.m.Y'))?></p></div><nav class="period" aria-label="Период отчёта"><?php foreach ([7,30,90] as $p): ?><a <?= $period===$p ? 'aria-current="page" class="active"' : '' ?> href="?days=<?=$p?>&amp;dashboard=<?=esc($provider->id())?>"><?=$p?> дней</a><?php endforeach ?></nav></div><nav class="dashboard-tabs" aria-label="Дашборды"><a href="?days=<?=$period?>">Сайт</a><?php foreach ($providers as $id=>$entry): ?><a <?= $id===$provider->id() ? 'aria-current="page" class="active"' : '' ?> href="?days=<?=$period?>&amp;dashboard=<?=esc($id)?>"><?=esc($entry->title())?></a><?php endforeach ?></nav><?php if ($report===null): ?><section class="panel empty"><strong>Не удалось получить данные.</strong><p>Проверьте настройки источника в приватной папке. Основной счётчик продолжает работать.</p></section><?php else: ?><div class="metrics extension-metrics"><?php foreach ($report['metrics'] as $metric): ?><section><span class="metric-label"><?=esc($metric['label'])?></span><strong><?=number_format($metric['value'], $metric['unit']==='count'?0:2, ',', ' ')?></strong><small><?=esc(['RUB'=>'рублей','count'=>'за выбранный период','percent'=>'процентов'][$metric['unit']])?></small></section><?php endforeach ?></div><section class="bottom-note"><div><strong>Источник данных</strong><p><?=esc($report['note'])?></p><p>Период и часовой пояс: <?=esc($cfg['timezone'])?>. Этот модуль не приписывает расходы конкретным посетителям и не рассчитывает окупаемость рекламы.</p></div></section><?php endif ?></main><footer class="footer"><span>Своя статистика / 1.0 / MIT</span><a href="index.php">К основной сводке ↗</a></footer></div></body></html>
